def all_prefixes(string: Union[str, int]) -> Tuple[List[str], Tuple[int, ...]]:
    s = str(string)
    def helper(i: int) -> List[str]:
        if i > len(s):
            return []
        return [s[:i]] + helper(i + 1)
    prefixes = helper(1)
    lengths = tuple(len(p) for p in prefixes)
    return prefixes, lengths
