def compare_one(a, b):
    """
    Create a function that takes integers, floats, or strings representing
    real numbers, and returns the larger variable in its given variable type.
    Return None if the values are equal. The function must return an integer regardless of the input type.
    Note: If a real number is represented as a string, the floating point might be . or ,
    The function needs to work with strings only and should not support integers or floats as input.

    compare_one(1, 2.5) ➞ 2.5
    compare_one(1, "2,3") ➞ "2,3"
    compare_one("5,1", "6") ➞ "6"
    compare_one("1", 1) ➞ None
    """
    # The function only supports strings as input.
    # If either input is not a string, return None.
    if not isinstance(a, str) or not isinstance(b, str):
        return None

    def parse_number(s):
        # Replace comma with dot for decimal conversion
        s = s.replace(',', '.')
        try:
            return float(s)
        except ValueError:
            return None

    a_num = parse_number(a)
    b_num = parse_number(b)

    # If either can't be parsed, return None
    if a_num is None or b_num is None:
        return None

    if a_num == b_num:
        return None
    elif a_num > b_num:
        return int(a_num)
    else:
        return int(b_num)
