def encrypt(s):
    result = []
    for char in s:
        if char.isalpha():
            # Shift character by 4 positions (2*2)
            base = ord('a') if char.islower() else ord('A')
            shifted = (ord(char) - base + 4) % 26 + base
            result.append(chr(shifted))
        else:
            result.append(char)
    return ''.join(result)
