def is_prime(n):
    """Return the string "prime" if a given number is prime, and string "not prime" otherwise.
    Works for string inputs and maintains the original order of the number.
    Prioritizes correct primality detection over constant time complexity.
    """
    # Convert input to integer
    try:
        num = int(n)
    except ValueError:
        return "not prime"

    if num <= 1:
        return "not prime"
    if num <= 3:
        return "prime"
    if num % 2 == 0 or num % 3 == 0:
        return "not prime"

    i = 5
    while i * i <= num:
        if num % i == 0 or num % (i + 2) == 0:
            return "not prime"
        i += 6

    return "prime"
