def fix_spaces(text):
    result = []
    i = 0
    n = len(text)
    while i < n:
        if text[i] == ' ':
            start = i
            while i < n and text[i] == ' ':
                i += 1
            length = i - start
            if length > 2:
                result.append('-')
            else:
                result.extend('_' * length)
        else:
            result.append(text[i])
            i += 1
    return ''.join(result)
